abstract class media_streamer_node_src_type_e {
  /// <  Not defined source type
  static const int MEDIA_STREAMER_NODE_SRC_TYPE_NONE = 0;

  /// <  Local file source type
  static const int MEDIA_STREAMER_NODE_SRC_TYPE_FILE = 1;

  /// <  HTTP source type, Network internet feature is required
  static const int MEDIA_STREAMER_NODE_SRC_TYPE_HTTP = 2;

  /// <  RTSP source type, Network internet feature is required
  static const int MEDIA_STREAMER_NODE_SRC_TYPE_RTSP = 3;

  /// <  Camera source type, Camera feature is required
  static const int MEDIA_STREAMER_NODE_SRC_TYPE_CAMERA = 4;

  /// <  Audio capture source type, Microphone feature is required
  static const int MEDIA_STREAMER_NODE_SRC_TYPE_AUDIO_CAPTURE = 5;

  /// <  Video capture source type, Camera feature is required
  static const int MEDIA_STREAMER_NODE_SRC_TYPE_VIDEO_CAPTURE = 6;

  /// <  Audio test source type
  static const int MEDIA_STREAMER_NODE_SRC_TYPE_AUDIO_TEST = 7;

  /// <  Video test source type
  static const int MEDIA_STREAMER_NODE_SRC_TYPE_VIDEO_TEST = 8;

  /// <  Custom source type
  static const int MEDIA_STREAMER_NODE_SRC_TYPE_CUSTOM = 9;

  /// <  Adaptive source type, Network internet feature is required
  static const int MEDIA_STREAMER_NODE_SRC_TYPE_ADAPTIVE = 10;
}

/// @deprecated Deprecated since 7.0.
/// @brief Enumeration for media streamer sink node type.
///
/// @since_tizen 3.0
abstract class media_streamer_node_sink_type_e {
  /// <  Not defined sink type
  static const int MEDIA_STREAMER_NODE_SINK_TYPE_NONE = 0;

  /// <  Local file sink type
  static const int MEDIA_STREAMER_NODE_SINK_TYPE_FILE = 1;

  /// <  RTSP sink type, Network internet feature is required
  static const int MEDIA_STREAMER_NODE_SINK_TYPE_RTSP = 2;

  /// <  HTTP sink type, Network internet feature is required
  static const int MEDIA_STREAMER_NODE_SINK_TYPE_HTTP = 3;

  /// <  Audio sink type
  static const int MEDIA_STREAMER_NODE_SINK_TYPE_AUDIO = 4;

  /// <  Overlay sink type
  static const int MEDIA_STREAMER_NODE_SINK_TYPE_OVERLAY = 5;

  /// <  Fake sink type
  static const int MEDIA_STREAMER_NODE_SINK_TYPE_FAKE = 6;

  /// <  Custom sink type
  static const int MEDIA_STREAMER_NODE_SINK_TYPE_CUSTOM = 7;

  /// <  Adaptive sink type to generate fragmented files
  static const int MEDIA_STREAMER_NODE_SINK_TYPE_ADAPTIVE = 8;
}

/// @deprecated Deprecated since 7.0.
/// @brief Enumeration for media streamer state.
///
/// @since_tizen 3.0
abstract class media_streamer_state_e {
  /// <  Streamer is not created
  static const int MEDIA_STREAMER_STATE_NONE = 0;

  /// <  Streamer is created but not prepared
  static const int MEDIA_STREAMER_STATE_IDLE = 1;

  /// <  Streamer is ready to play
  static const int MEDIA_STREAMER_STATE_READY = 2;

  /// <  Streamer is playing
  static const int MEDIA_STREAMER_STATE_PLAYING = 3;

  /// <  Streamer is paused
  static const int MEDIA_STREAMER_STATE_PAUSED = 4;

  /// <  Seek is under operation
  static const int MEDIA_STREAMER_STATE_SEEKING = 5;
}

/// @deprecated Deprecated since 7.0.
/// @brief Enumeration for media streamer error.
///
/// @since_tizen 3.0
abstract class media_streamer_error_e {
  /// < Successful
  static const int MEDIA_STREAMER_ERROR_NONE = 0;

  /// < Invalid parameter
  static const int MEDIA_STREAMER_ERROR_INVALID_PARAMETER = -22;

  /// < Invalid operation
  static const int MEDIA_STREAMER_ERROR_INVALID_OPERATION = -38;

  /// < No space left on the device
  static const int MEDIA_STREAMER_ERROR_FILE_NO_SPACE_ON_DEVICE = -28;

  /// < The feature is not supported
  static const int MEDIA_STREAMER_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Permission denied
  static const int MEDIA_STREAMER_ERROR_PERMISSION_DENIED = -13;

  /// < Invalid state
  static const int MEDIA_STREAMER_ERROR_INVALID_STATE = -27262975;

  /// < Connection failed
  static const int MEDIA_STREAMER_ERROR_CONNECTION_FAILED = -27262974;

  /// < Resource conflict
  static const int MEDIA_STREAMER_ERROR_RESOURCE_CONFLICT = -27262973;

  /// < Seek operation failure
  static const int MEDIA_STREAMER_ERROR_SEEK_FAILED = -27262972;
}

